sys_script_include.script:
var PatientUtils = Class.create();
PatientUtils.prototype = {
    initialize: function() {
    },
      getPatientDetailsById: function (patientId) {
        var gr = new GlideRecord('u_patient_record');
        gr.addQuery('u_patient_id', patientId);
        gr.query();
        if (gr.next()) {
            return gr.getValue('sys_id') + ';' + gr.getValue('u_first_name') + ';' + gr.getValue('u_last_name');
        }
        return false;
    },

    // 2. Check if patient is VIP
    isVIP: function (patientId) {
        var gr = new GlideRecord('u_patient_record');
        gr.addQuery('u_patient_id', patientId);
        gr.query();
        if (gr.next()) {
            return gr.getValue('u_vip'); // true/false
        }
        return false;
    },

    // 3. Calculate age
    calculateAge: function (patientId) {
        var gr = new GlideRecord('u_patient_record');
        gr.addQuery('u_patient_id', patientId);
        gr.query();
        if (gr.next()) {
            var dob = new GlideDate(gr.getValue('u_date_of_birth'));
            var today = new GlideDate();
            var age = parseInt((today.getNumericValue() - dob.getNumericValue()) / 365);
            return age.toString();
        }
        return false;
    },

    // 4. Fetch appointments
    getAppointments: function (patientId) {
        var result = '';
        var gr = new GlideRecord('u_appointment');
        gr.addQuery('u_patient_id.u_patient_id', patientId);
        gr.query();
        while (gr.next()) {
            result += gr.getValue('u_appointment_id') + ';' + gr.getValue('u_appointment_date') + '\n';
        }
        return result || false;
    },

    // 5. Fetch medications
    getMedications: function (patientId) {
        var result = '';
        var gr = new GlideRecord('u_medication');
        gr.addQuery('u_patient_id.u_patient_id', patientId);
        gr.query();
        while (gr.next()) {
            result += gr.getValue('u_medication_name') + ';' + gr.getValue('u_dosage') + '\n';
        }
        return result || false;
    },

    // 6. Fetch lab tests
    getLabTests: function (patientId) {
        var result = '';
        var gr = new GlideRecord('u_lab_test');
        gr.addQuery('u_patient_id.u_patient_id', patientId);
        gr.query();
        while (gr.next()) {
            result += gr.getValue('u_test_type') + ';' + gr.getValue('u_scheduled_date') + '\n';
        }
        return result || false;
    },

    // 7. Fetch billing records
    getBillingRecords: function (patientId) {
        var result = '';
        var gr = new GlideRecord('u_billing');
        gr.addQuery('u_patient_id.u_patient_id', patientId);
        gr.query();
        while (gr.next()) {
            result += gr.getValue('u_billing_id') + ';' + gr.getValue('u_total_amount') + '\n';
        }
        return result || false;
    },

    // 8. Fetch insurance policies
    getInsurancePolicies: function (patientId) {
        var result = '';
        var gr = new GlideRecord('u_insurance');
        gr.addQuery('u_patient_id.u_patient_id', patientId);
        gr.query();
        while (gr.next()) {
            result += gr.getValue('u_policy_number') + ';' + gr.getValue('u_provider') + '\n';
        }
        return result || false;
    },
    type: 'PatientUtils'
};
